"""Save a Mermaid diagram of the compiled graph to docs/graph.md.

Run from the project root:  python scripts/export_graph.py
"""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "src"))

from langgraph.checkpoint.memory import InMemorySaver

from agent.graph import build_graph

# With a checkpointer, so that the human_review node is drawn too
mermaid = build_graph(InMemorySaver()).get_graph().draw_mermaid()
(ROOT / "docs" / "graph.md").write_text(
    "# Agent graph\n\n"
    "Generated by `scripts/export_graph.py` from the compiled LangGraph. "
    "Solid arrows are fixed edges, dotted arrows are conditional edges (the router's choices).\n\n"
    f"```mermaid\n{mermaid}\n```\n",
    encoding="utf-8",
)
print("saved docs/graph.md")
